  ('c4c8c0bc-4d6a-4f87-b5a6-e462af353c93', $$Economie$$, $$VWO$$, $$Een gewenste prijsstijging van friet?$$, $$VWO Economie 2021-II$$),
  ('56bb0f0c-494c-464f-857d-bfeb0c2f555d', $$Economie$$, $$VWO$$, $$Verzekeren op maat$$, $$VWO Economie 2021-II$$),
  ('a914e6e8-f585-4f80-bff9-c7d4ca3e669d', $$Economie$$, $$VWO$$, $$Groei op de klippen$$, $$VWO Economie 2021-II$$),
  ('2b78912f-cc54-42a2-95ce-c06365c919ea', $$Economie$$, $$VWO$$, $$Recessie door het buurland$$, $$VWO Economie 2021-II$$),
