insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('60aede69-8b21-42d8-84ee-0356970461b2', 'c4c8c0bc-4d6a-4f87-b5a6-e462af353c93', $$inleiding: heffing op friet van 20% van de verkoopprijs$$,
   $$economie-vwo-2021-ii-een-gewenste-prijsstijging-van-friet-context1.png$$,
   $$De centrale overheid in een land probeert de volksgezondheid te verbeteren door een heffing op tabak en alcohol. Per 1-1-2021 wordt ook een heffing ingevoerd op friet: 20% van de verkoopprijs.$$, 'inline'),
  ('7536b07e-a0d0-4d25-872a-74d2e1b2e5d0', 'c4c8c0bc-4d6a-4f87-b5a6-e462af353c93', $$gemeente Sanuscha: pay-off matrix voor de cafetaria's van Jan en Willem$$,
   $$economie-vwo-2021-ii-een-gewenste-prijsstijging-van-friet-context2.png$$,
   $$De gemeente Sanuscha bestudeert de gevolgen van de invoering van de heffing op friet voor twee cafetaria’s: die van Jan en die van Willem. Beide cafetaria’s zijn eenmanszaken en beide eigenaar-ondernemers betalen inkomstenbelasting. De wethouder van Economische Zaken heeft enkele onderzoekers de opdracht gegeven een pay-off matrix op te stellen om de gevolgen van de heffing te voorspellen.$$, 'inline'),
  ('31ec084f-5193-400f-8a54-391b320faa25', 'c4c8c0bc-4d6a-4f87-b5a6-e462af353c93', $$matrix 1: verwachte omzetten van twee cafetaria's, met toelichting$$,
   $$economie-vwo-2021-ii-een-gewenste-prijsstijging-van-friet-context3.png$$,
   $$Matrix 1 de verwachte omzetten van twee cafetaria’s in Sanuscha
| Willem verandert zijn frietprijs op 1-1-2021 niet | Willem verhoogt zijn frietprijs op 1-1-2021 met 20%
Jan verandert zijn frietprijs op 1-1-2021 niet | (10.000 + 5.000), (9.000 + 4.000) | (10.500 + 5.250), (8.000 + 3.600)
Jan verhoogt zijn frietprijs op 1-1-2021 met 20% | (9.000 + 4.500), (9.300 + 4.120) | (9.700 + 4.650), (8.500 + 3.850)
Toelichting bij de matrix:
− de omzetten zijn maandgemiddelden en luiden in euro’s. Alle omzetten zijn na afdracht van indirecte belastingen.
− per cafetaria staat eerst de totale omzet aan friet en vervolgens de totale omzet aan andere producten uit het assortiment
− de prijs van een zakje friet bedraagt bij beide cafetaria’s vlak voor invoering van de heffing € 2
− overige prijzen blijven gelijk
− beide eigenaren-ondernemers streven naar een zo hoog mogelijke totale omzet van het gehele assortiment.$$, 'inline'),
  ('cb3421dc-7723-488a-a211-eeae46d3b6a4', 'c4c8c0bc-4d6a-4f87-b5a6-e462af353c93', $$vraag naar friet bij Willem is prijselastisch$$,
   $$economie-vwo-2021-ii-een-gewenste-prijsstijging-van-friet-context4.png$$,
   $$Uit de gegevens uit de matrix is af te leiden dat de vraag naar friet van Willem’s cafetaria prijselastisch is.$$, 'inline'),
  ('c8bbec06-f6a7-449e-9781-7d9e31f5d856', 'c4c8c0bc-4d6a-4f87-b5a6-e462af353c93', $$matrix voorspelt gevolgen voor de frietconsumptie$$,
   $$economie-vwo-2021-ii-een-gewenste-prijsstijging-van-friet-context5.png$$,
   $$De matrix bevat een voorspelling over de gevolgen van de heffing voor de consumptie van friet in de gemeente Sanuscha.$$, 'inline'),
  ('a82a32b2-9c3d-4715-a463-d1cc74ceaeee', 'c4c8c0bc-4d6a-4f87-b5a6-e462af353c93', $$bewustwordingscampagne voor gezonde producten$$,
   $$economie-vwo-2021-ii-een-gewenste-prijsstijging-van-friet-context6.png$$,
   $$De gemeente wil dat beide cafetaria’s veel meer gezonde producten in hun assortiment gaan opnemen. Daarom wil ze een bewustwordingscampagne starten op de basisscholen en de middelbare school in de gemeente om de leerlingen te laten kennismaken met gezonde alternatieven.$$, 'inline'),
  ('6062869e-382e-4e98-9fc5-03416655b326', 'c4c8c0bc-4d6a-4f87-b5a6-e462af353c93', $$onderzoekers: lagere betalingsbereidheid, geen winst meer op friet$$,
   $$economie-vwo-2021-ii-een-gewenste-prijsstijging-van-friet-context7.png$$,
   $$De onderzoekers stellen dat een succesvolle bewustwordingscampagne de betalingsbereidheid voor friet zodanig kan veranderen dat, bij een ongewijzigd assortiment, beide cafetaria’s op termijn geen winst meer kunnen maken op de verkoop van friet.$$, 'inline'),
  ('847d38c4-51df-4944-8168-1decd1c44599', 'c4c8c0bc-4d6a-4f87-b5a6-e462af353c93', $$wethouder: fiscale prikkel via aftrekpost of heffingskorting$$,
   $$economie-vwo-2021-ii-een-gewenste-prijsstijging-van-friet-context8.png$$,
   $$Om het voor de cafetaria’s aantrekkelijk te maken om te investeren in een assortiment met gezonde producten stuurt de wethouder van Economische Zaken een voorstel naar de centrale overheid. Daarin pleit hij voor het volgende: “De cafetaria’s die hun assortiment voor ten minste 75% uit gezonde producten samenstellen, zouden een fiscale prikkel moeten krijgen in de vorm van een vast bedrag als extra aftrekpost of als extra heffingskorting.” De wethouder wil graag die fiscale prikkel ingevoerd hebben die het best stuurt richting de gewenste verandering van het assortiment.$$, 'inline'),
  ('15621321-010b-4394-9d2e-3eac7349bf31', '56bb0f0c-494c-464f-857d-bfeb0c2f555d', $$inleiding: StartPolis voor jonge autobezitters$$,
   $$economie-vwo-2021-ii-verzekeren-op-maat-context1.png$$,
   $$Verzekeringsmaatschappij YouSure wil autoverzekeringen aanbieden voor jongeren die voor het eerst een eigen autoverzekering afsluiten: de StartPolis. Deze verzekering zal de schade aan de eigen auto dekken en kan worden afgesloten naast de verplichte verzekering voor wettelijke aansprakelijkheid (WA), die alleen de schade aan de tegenpartij dekt.$$, 'inline'),
  ('d3382f77-85e7-4b03-b489-40d87dfc3549', '56bb0f0c-494c-464f-857d-bfeb0c2f555d', $$variabele poliskosten € 25 en constante kosten € 500.000$$,
   $$economie-vwo-2021-ii-verzekeren-op-maat-context2.png$$,
   $$Per jaar bedragen de gemiddelde verwachte variabele poliskosten voor de Startpolis (exclusief schade-uitkering) € 25 en de totale verwachte constante kosten € 500.000. YouSure streeft naar maximale winst.$$, 'inline'),
  ('1e882cd6-0068-44fe-b572-0ae230c33607', '56bb0f0c-494c-464f-857d-bfeb0c2f555d', $$simulatie met twee risicogroepen A en B$$,
   $$economie-vwo-2021-ii-verzekeren-op-maat-context3.png$$,
   $$Om een indruk te krijgen van de winstgevendheid van de StartPolis heeft een onderzoeker van YouSure een simulatie uitgevoerd. In deze simulatie wordt uitgegaan van één doelgroep, opgedeeld in twee risicogroepen: risicogroep A en risicogroep B (tabel 1).$$, 'inline'),
  ('62591610-2e4c-40e8-9fc7-a85ddde22e75', '56bb0f0c-494c-464f-857d-bfeb0c2f555d', $$tabel 1: aannames over risicogroepen van autobezitters$$,
   $$economie-vwo-2021-ii-verzekeren-op-maat-context4.png$$,
   $$Tabel 1 Aannames over risicogroepen van autobezitters
risicogroep | kans op schade per jaar | gemiddeld schadebedrag | aantal autobezitters in de groep
A | 10% | € 6.000 | 10.000
B | 7% | € 5.500 | 15.000$$, 'inline'),
  ('2d290da8-8ded-4832-83ff-d2be577e48cb', '56bb0f0c-494c-464f-857d-bfeb0c2f555d', $$overige aannames: informatieasymmetrie en betalingsbereidheid 120%$$,
   $$economie-vwo-2021-ii-verzekeren-op-maat-context5.png$$,
   $$Overige aannames bij de simulatie:
− De maatschappij weet van een individuele verzekerde niet tot welke risicogroep die behoort. Alle verzekerden hebben zelf wel een juist beeld van hun eigen kans op schade en de gemiddelde hoogte van de schade.
− De maatschappij gaat ervan uit dat de betalingsbereidheid van alle verzekerden gelijk is aan 120% van het gemiddelde verwachte schadebedrag dat voor hen van toepassing is.$$, 'inline'),
  ('e6ebddc7-37b9-4210-b158-9ee30880a73c', '56bb0f0c-494c-464f-857d-bfeb0c2f555d', $$optie uniforme premie; stellingen i en ii van de manager$$,
   $$economie-vwo-2021-ii-verzekeren-op-maat-context6.png$$,
   $$Een optie is om de StartPolis aan beide doelgroepen aan te bieden met een uniforme premie. Een manager van YouSure stelt: i Als de StartPolis wordt aangeboden voor een premie die gelijk is aan de betalingsbereidheid van autobezitters uit groep A, dan zal deze winstgevend zijn. ii Als de uniforme premie wordt verlaagd tot de betalingsbereidheid van autobezitters in groep B, dan zal verlies worden gemaakt.$$, 'inline'),
  ('e29e5389-00ed-451c-8069-9445ceaef7ca', '56bb0f0c-494c-464f-857d-bfeb0c2f555d', $$premiedifferentiatie met de Carmonitor$$,
   $$economie-vwo-2021-ii-verzekeren-op-maat-context7.png$$,
   $$YouSure kiest voor optie i. De onderzoeker komt met een voorstel om premiedifferentiatie toe te passen. Verzekerden komen in aanmerking voor een lagere premie als zij een nieuw apparaat (de Carmonitor) in hun auto laten installeren. De Carmonitor registreert het rijgedrag (hoe de verzekerde optrekt, remt en stuurt) en geeft dit door aan de verzekeraar. Hiermee kunnen verzekerden bewijzen dat ze bij groep B horen en kunnen ze een lagere premie krijgen. De Carmonitor wordt hun kosteloos ter beschikking gesteld. De kosten van de Carmonitor komen voor de verzekeraar tot uiting in een toename van de variabele poliskosten.$$, 'inline'),
  ('3339cf4f-4e50-49b0-b75f-9f226ad0e62c', '56bb0f0c-494c-464f-857d-bfeb0c2f555d', $$onderzoeker: moral hazard neemt af$$,
   $$economie-vwo-2021-ii-verzekeren-op-maat-context8.png$$,
   $$De onderzoeker concludeert: “Moral hazard zal afnemen door dit plan voor premiedifferentiatie. Hierdoor veranderen twee gegevens in de tabel en stijgt de winstgevendheid van de verzekering.”$$, 'inline'),
  ('2e842241-1362-4d09-b352-68bfcce4b6f6', '56bb0f0c-494c-464f-857d-bfeb0c2f555d', $$onderzoeker: lage risico's verzekeren vergroot totaal surplus$$,
   $$economie-vwo-2021-ii-verzekeren-op-maat-context9.png$$,
   $$Door premiedifferentiatie toe te passen hoopt de onderzoeker dat verzekerden uit groep B zich ook gaan verzekeren. De onderzoeker stelt: “Als mensen met een laag risico zich verzekeren, heeft dit een positief effect op het totale surplus op dit deel van de verzekeringsmarkt.”$$, 'inline'),
  ('a6698be1-792f-40cf-a44a-7bb0550cbaed', '56bb0f0c-494c-464f-857d-bfeb0c2f555d', $$consumentenbond: onvolledige informatie en transactiekosten$$,
   $$economie-vwo-2021-ii-verzekeren-op-maat-context10.png$$,
   $$Een woordvoerder van de consumentenbond ziet het idee van de Carmonitor niet zitten. Hij stelt dat het niet lang duurt voordat andere verzekeraars eenzelfde apparaat gaan aanbieden, ieder onder zijn eigen voorwaarden. Als gevolg hiervan kan onvolledige informatie ontstaan en de transactiekosten van potentiële verzekerden kunnen hierdoor toenemen.$$, 'inline'),
  ('fde92c42-73b1-49ae-8a4b-4cfb4d6c684e', 'a914e6e8-f585-4f80-bff9-c7d4ca3e669d', $$inleiding: Turkse bedrijven lenen in euro's; lira daalt 40%$$,
   $$economie-vwo-2021-ii-groei-op-de-klippen-context1.png$$,
   $$Turkije behoorde tot 2016 tot de economisch opkomende landen met een sterke groei van het bbp. Deze groei was vooral gebaseerd op investeringen in de bouwsector. Turkse bedrijven hebben deze investeringen gefinancierd door in de eurozone leningen af te sluiten tegen de lage rente die daar geldt. In 2017 verloren internationale beleggers het vertrouwen in de ontwikkeling van de Turkse economie. De Turkse lira daalde met 40% in waarde ten opzichte van de euro.$$, 'inline'),
  ('23c55f76-d36f-42e9-b00d-948cc54d030f', 'a914e6e8-f585-4f80-bff9-c7d4ca3e669d', $$overheidsgarantie op bedrijfskredieten; analist over belastingen en rente$$,
   $$economie-vwo-2021-ii-groei-op-de-klippen-context2.png$$,
   $$De Turkse overheid heeft zich voor veel van deze Turkse bedrijfskredieten garant gesteld. De garantie geldt uitsluitend voor de aflossing. Een analist schrijft hierover: “In 2017 daalde de lira, nam de inflatie toe en dreigde de economie van Turkije in een recessie te komen. De Turkse regering moet, in verband met de kredietgarantie aan bedrijven, de belastingen op termijn verhogen en zal van de Turkse centrale bank eisen de rente laag te houden om de recessie te vermijden. De Turkse centrale bank zal de rente juist willen verhogen om de inflatie te bestrijden.”$$, 'inline'),
  ('07438535-e99d-4343-baaa-cc3cf11572cf', 'a914e6e8-f585-4f80-bff9-c7d4ca3e669d', $$gevolgen van de Turkse recessie voor twee landengroepen$$,
   $$economie-vwo-2021-ii-groei-op-de-klippen-context3.png$$,
   $$De analist geeft ook aan dat een recessie in Turkije gevolgen kan hebben voor het bbp van andere landen. Hij onderscheidt twee landengroepen:
− de voornaamste handelspartners Bulgarije, Iran en Georgië,
− de eurolanden via het Europese bankwezen.$$, 'inline'),
  ('6ca42992-1ff4-48aa-9003-dc769b82ff72', 'a914e6e8-f585-4f80-bff9-c7d4ca3e669d', $$daling lira: exportwaarde +36%, prijselasticiteit importvolume −0,75$$,
   $$economie-vwo-2021-ii-groei-op-de-klippen-context4.png$$,
   $$De analist stelt dat de daling van de wisselkoers het saldo op de lopende rekening van Turkije positief beïnvloedt. Hij stelt het volgende: “Door de daling van de lira van 40% ten opzichte van de euro is de exportwaarde in eigen valuta gestegen met 36%. De importwaarde zal ook veranderen en de prijselasticiteit van het importvolume wordt op −0,75 geschat.” Hij gaat ervan uit dat overige factoren constant blijven.$$, 'inline'),
  ('332fe702-ba04-424e-b1b2-92247fcadd74', 'a914e6e8-f585-4f80-bff9-c7d4ca3e669d', $$formule prijselasticiteit van het importvolume$$,
   $$economie-vwo-2021-ii-groei-op-de-klippen-context5.png$$,
   $$Prijselasticiteit van het importvolume:
Eimport = procentuele verandering importvolume / procentuele verandering prijs van import in lira''s$$, 'inline'),
  ('a930e217-e21c-4bb9-8ed5-89b98c46d25c', 'a914e6e8-f585-4f80-bff9-c7d4ca3e669d', $$renteverhoging kan recessie via de valutamarkt verergeren of afzwakken$$,
   $$economie-vwo-2021-ii-groei-op-de-klippen-context6.png$$,
   $$Ten slotte merkt de analist in 2018 op dat een renteverhoging onvermijdelijk zal zijn om de inflatie te bestrijden. Over het effect daarvan op de ontwikkeling van een mogelijke recessie concludeert hij: “Een verhoging van de rente kan, via de valutamarkt, een recessie zowel verergeren als afzwakken.”$$, 'inline'),
  ('e2dd3038-e011-4dd5-a7ed-b2d50eb738d0', '2b78912f-cc54-42a2-95ce-c06365c919ea', $$inleiding: recessie bij het buurland van Hetland$$,
   $$economie-vwo-2021-ii-recessie-door-het-buurland-context1.png$$,
   $$In Hetland gaat het economisch voor de wind totdat bij het buurland (de belangrijkste handelspartner) een recessie optreedt. De overheid en de centrale bank van Hetland bekijken de situatie en overwegen in te grijpen.$$, 'inline'),
  ('d7dafc49-f5c1-43d3-a25b-90fcbd91d3e5', '2b78912f-cc54-42a2-95ce-c06365c919ea', $$doelstellingen overheid (werkloosheid) en centrale bank (prijsstabiliteit)$$,
   $$economie-vwo-2021-ii-recessie-door-het-buurland-context2.png$$,
   $$Beide instanties hanteren het macro-economische model dat te zien is in figuur 1. Hierbij wordt uitgegaan van een flexibele arbeidsmarkt en een constante arbeidsproductiviteit. De overheid heeft als enige doelstelling de werkloosheid te bestrijden. De centrale bank heeft als enige doelstelling de prijsstabiliteit handhaven.$$, 'inline'),
  ('509fbf81-6db3-48a0-8e42-ef1e5a69b395', '2b78912f-cc54-42a2-95ce-c06365c919ea', $$figuur 1: effect van recessie in buurland op Hetland, met legenda$$,
   $$economie-vwo-2021-ii-recessie-door-het-buurland-context3.png$$,
   $$Figuur 1 effect van recessie in buurland op Hetland
Grafiek van het prijspeil (P) tegen het reëel bbp (Yr) met dalende lijnen GV0 en GV1 (GV1 links van GV0), een verticale lijn GAlt bij Y0 en een horizontale lijn GAkt0 bij P0. Het oude evenwicht ligt bij (Y0, P0), het nieuwe bij (Y1, P0).
GV = geaggregeerde vraag; GA = geaggregeerd aanbod; lt = lange termijn; kt = korte termijn; 0 = oude situatie voor recessie buurland; 1 = nieuwe situatie na recessie buurland$$, 'inline'),
  ('a87e0277-c07a-4d17-97a9-6c0b3825afbf', '2b78912f-cc54-42a2-95ce-c06365c919ea', $$politicus: bedrijven moeten de prijzen verlagen$$,
   $$economie-vwo-2021-ii-recessie-door-het-buurland-context4.png$$,
   $$Een politicus in Hetland stelt dat bij een recessie de prijzen verlaagd moeten worden om zo de productie te stimuleren. Zij pleit er bij bedrijven voor om dit nu te doen.$$, 'inline'),
  ('afebf791-b6a6-4136-8286-2c534fe39e18', '2b78912f-cc54-42a2-95ce-c06365c919ea', $$overheid: centrale bank moet de geldhoeveelheid vergroten$$,
   $$economie-vwo-2021-ii-recessie-door-het-buurland-context5.png$$,
   $$De overheid stelt voor dat de centrale bank de geldhoeveelheid vergroot om hiermee de productie op de goederenmarkt te stimuleren.$$, 'inline'),
  ('5f008efd-1e51-4e5d-b218-dd4295cece82', '2b78912f-cc54-42a2-95ce-c06365c919ea', $$aanbodschok door duurdere geïmporteerde grondstoffen$$,
   $$economie-vwo-2021-ii-recessie-door-het-buurland-context6.png$$,
   $$Nog voordat de overheid of de centrale bank kan ingrijpen, treedt er een aanbodschok op: een plotselinge stijging van de prijzen van geïmporteerde grondstoffen. Hierdoor ontstaat er een nieuw evenwicht (P2, Y2). Dit is weergegeven in figuur 2.$$, 'inline'),
  ('c31ca688-f44c-497d-aad2-13e7ebcf0fa7', '2b78912f-cc54-42a2-95ce-c06365c919ea', $$figuur 2: aanbodschok en de gevolgen voor Hetland$$,
   $$economie-vwo-2021-ii-recessie-door-het-buurland-context7.png$$,
   $$Figuur 2 aanbodschok en de gevolgen voor Hetland
Grafiek van het prijspeil (P) tegen de reële productie (Yr) met een dalende lijn GV1 en drie horizontale lijnen GAkt0 (bij P0), GAkt2 (bij P2) en GAkt3 (bij P3). De snijpunten met GV1 liggen bij Y1, Y2 en Y3; Y0 ligt rechts van Y1.$$, 'inline'),
  ('e1962006-0d8f-4fe8-9bb3-4f31cdc3bf11', '2b78912f-cc54-42a2-95ce-c06365c919ea', $$stagflatie; prijspeil stijgt door hogere inflatieverwachtingen$$,
   $$economie-vwo-2021-ii-recessie-door-het-buurland-context8.png$$,
   $$Door de aanbodschok ontstaat er een situatie van ‘stagflatie’: een versterkte recessie in combinatie met inflatie. Het prijspeil stijgt verder (van P2 naar P3) doordat de inflatieverwachtingen hoger zijn geworden.$$, 'inline'),
  ('7b5dc2b8-60b1-47ac-b9c0-e11f16ea36cf', '2b78912f-cc54-42a2-95ce-c06365c919ea', $$twee maatregelen: lagere inkomstenbelasting en lagere milieuheffingen$$,
   $$economie-vwo-2021-ii-recessie-door-het-buurland-context9.png$$,
   $$De overheid komt na overleg met de centrale bank met twee maatregelen, gericht op het herstel van de economie:
− verlaging van de tarieven van de inkomstenbelasting.
− verlaging van milieuheffingen voor bedrijven. In de analyse van de overheid wordt de lange-termijnaanbodcurve als constant geacht en kijkt men enkel naar de korte termijn.$$, 'inline'),
  ('3e4cdee2-1a15-4c40-b6b4-1311cb47867f', '001c8d75-7f1e-4425-9cba-d3eaea93a74b', $$inleiding: dividendbelasting 15% met vrijstelling van € 10.000$$,
   $$economie-vwo-2021-ii-dividendbelasting-context1.png$$,
   $$In een euroland belast de overheid in 2019 de winstuitkeringen (dividenden) van binnenlandse en buitenlandse beleggers met een tarief van 15%. De eerste € 10.000 wordt vrijgesteld van belasting.$$, 'inline'),
  ('44ba44f1-453d-4963-9a17-ead178fd756b', '001c8d75-7f1e-4425-9cba-d3eaea93a74b', $$minister Hoeksma wil de dividendbelasting afschaffen$$,
   $$economie-vwo-2021-ii-dividendbelasting-context2.png$$,
   $$Per 1-1-2020 is minister Hoeksma van Financiën van plan om de dividendbelasting af te schaffen. Zij wil daarmee buitenlands kapitaal aantrekken. Ze mikt hierbij op de hogere inkomens, die over het algemeen relatief meer beleggen in aandelen dan de lagere inkomens.$$, 'inline'),
  ('57dd7b47-addb-4e72-8d10-2bdaa4430f42', '001c8d75-7f1e-4425-9cba-d3eaea93a74b', $$vereenvoudigd model van de aandelenmarkt$$,
   $$economie-vwo-2021-ii-dividendbelasting-context3.png$$,
   $$Om de gevolgen van Hoeksma’s voorstel op de aandelenmarkt van het land te analyseren gebruikt ze het volgende vereenvoudigde model:$$, 'inline'),
  ('b0c55a2f-89d8-4118-8a7e-f26641ff5dbc', '001c8d75-7f1e-4425-9cba-d3eaea93a74b', $$marktmodel van aandeel X voor en na afschaffing, met legenda en toelichting$$,
   $$economie-vwo-2021-ii-dividendbelasting-context4.png$$,
   $$| marktmodel van aandeel X voor het afschaffen van de dividendbelasting | marktmodel van aandeel X na het afschaffen van de dividendbelasting
vergelijking (1) | Qv = −2K + 9.000 | Qv = −2K + 9.600
vergelijking (2) | Qa = 398K − 5.000 | Qa = 348K − 5.000
Legenda
Qv = Collectieve vraag naar aandeel X in stuks
Qa = Collectief aanbod van aandeel X in stuks
K = Koers per aandeel X in euro’s
Toelichting: Aandeel X is al jaren in omloop en betreft een eigendomsbewijs van een belangrijke multinational. Aandelenkoers K wordt beschouwd als een goede indicator voor de algehele koersontwikkelingen op de aandelenbeurs in het land.$$, 'inline'),
  ('c232ff90-d172-4220-9eeb-bb87bfcc4a69', '001c8d75-7f1e-4425-9cba-d3eaea93a74b', $$Hoeksma: verwachte koerswinst meer dan 10%$$,
   $$economie-vwo-2021-ii-dividendbelasting-context5.png$$,
   $$Minister Hoeksma stelt dat de verwachte koerswinst op de aandelenmarkt als gevolg van de afschaffing van de dividendbelasting meer dan 10% is.$$, 'inline'),
  ('3cf241dd-77f1-48b1-8f18-e566c125bad7', '001c8d75-7f1e-4425-9cba-d3eaea93a74b', $$koersstijgingen, consumentenvertrouwen en inverdieneffecten$$,
   $$economie-vwo-2021-ii-dividendbelasting-context6.png$$,
   $$De afschaffing van de dividendbelasting leidt tot koersstijgingen op de aandelenmarkt. Hierdoor zal het consumentenvertrouwen toenemen en kunnen uiteindelijk inverdieneffecten optreden.$$, 'inline'),
  ('4e35b572-21ff-46ba-aa25-df54f1c1546e', '001c8d75-7f1e-4425-9cba-d3eaea93a74b', $$minister Dams is tegen het voorstel$$,
   $$economie-vwo-2021-ii-dividendbelasting-context7.png$$,
   $$Minister Dams van Sociale Zaken is tegen het voorstel van haar collega van Financiën. Minister Dams kijkt daarbij naar de volgende tabellen:$$, 'inline'),
  ('e855cf75-7fe4-47fe-a523-f3dcaef57eae', '001c8d75-7f1e-4425-9cba-d3eaea93a74b', $$tabel 1: ontwikkeling arbeidsinkomensquote in het land en in vier buurlanden$$,
   $$economie-vwo-2021-ii-dividendbelasting-context8.png$$,
   $$Tabel 1 ontwikkeling arbeidsinkomensquote in het land en in vier buurlanden
| 2000 | 2005 | 2010 | 2015 | 2019
AIQ in eigen land | 0,74 | 0,73 | 0,71 | 0,69 | 0,68
Gemiddelde AIQ in vier buurlanden | 0,87 | 0,88 | 0,89 | 0,90 | 0,90$$, 'inline'),
  ('1d89af3d-9393-434b-bc2d-8cc43b17d140', '001c8d75-7f1e-4425-9cba-d3eaea93a74b', $$tabel 2: ontwikkeling van de Gini-coëfficiënt van de secundaire inkomensverdeling$$,
   $$economie-vwo-2021-ii-dividendbelasting-context9.png$$,
   $$Tabel 2 ontwikkeling van de Gini-coëfficiënt van de secundaire inkomensverdeling in het land
2000 | 2005 | 2010 | 2015 | 2019
0,49 | 0,52 | 0,52 | 0,55 | 0,56$$, 'inline'),
  ('1775078e-7a63-475f-828b-8c151f487bf6', '001c8d75-7f1e-4425-9cba-d3eaea93a74b', $$twee beweringen van minister Dams$$,
   $$economie-vwo-2021-ii-dividendbelasting-context10.png$$,
   $$Minister Dams beweert onder meer met verwijzing naar bovenstaande tabellen het volgende:
− “Buitenlandse ondernemingen zouden sowieso meer beleggen in ons land zonder het afschaffen van de dividendbelasting. Een aanwijzing hiervoor is de structurele ontwikkeling van de arbeidsinkomensquote.”
− “Ik vind het verwachte gevolg van het afschaffen van de dividendbelasting op de secundaire inkomensverdeling in het land hoogst ongewenst.”$$, 'inline'),
  ('e5de95bd-2f5c-4257-a3ac-5de6aeb82993', '001c8d75-7f1e-4425-9cba-d3eaea93a74b', $$Dams schrijft een reactie aan haar collega van Financiën$$,
   $$economie-vwo-2021-ii-dividendbelasting-context11.png$$,
   $$Minister Dams schrijft een reactie aan haar collega van Financiën om haar twee beweringen voor de volgende kabinetsvergadering alvast uit te leggen.$$, 'inline'),
  ('31a7bcae-0654-4d63-99cf-cab1b7580c98', '21cfe451-ed82-410d-be51-b6229ac3d1a0', $$inleiding: Zuiverwater (ZW) heft 70 euro per vervuilingseenheid; doel break-even$$,
   $$economie-vwo-2021-ii-afvalwater-een-schone-zaak-context1.png$$,
   $$In een gemeente zuivert waterzuiveringsbedrijf Zuiverwater (ZW) afvalwater dat door bedrijven in het riool is geloosd. Bedrijven betalen voor elke liter afvalwater een heffing van 70 euro per vervuilingseenheid (VE). ZW heeft specifieke investeringen gedaan en heeft als bedrijfsdoelstelling break-even draaien.$$, 'inline'),
  ('564b8ef1-1c33-45eb-a5b5-11c681c3c5bc', '21cfe451-ed82-410d-be51-b6229ac3d1a0', $$G4 overweegt eigen zuiveringsinstallatie; ZW moet onderhandelen$$,
   $$economie-vwo-2021-ii-afvalwater-een-schone-zaak-context2.png$$,
   $$Bedrijven kunnen ervoor kiezen om zelf hun afvalwater te zuiveren. Een groep van vier grote bedrijven (de G4) die samen op een bedrijventerrein zijn gevestigd overweegt een eigen zuiveringsinstallatie te bouwen. De G4 brengt ZW hiervan op de hoogte. ZW ziet zijn break-even doelstelling in gevaar komen en zal moeten onderhandelen met de G4 om tot een oplossing te komen.$$, 'inline'),
  ('dca5c4d6-1d99-43db-bac1-fb476d5052fa', '21cfe451-ed82-410d-be51-b6229ac3d1a0', $$instructie vraag 26: korting op de heffing per VE$$,
   $$economie-vwo-2021-ii-afvalwater-een-schone-zaak-context3.png$$,
   $$Gebruik bovenstaande tekst en tabellen 1 tot en met 3 bij vraag 26. Als ZW een korting op de heffing per VE aanbiedt, kan het verhinderen dat de G4 overstapt op een eigen zuiveringsinstallatie.$$, 'inline'),
  ('77091ecd-8441-4403-9c05-f4458ff0f29e', '21cfe451-ed82-410d-be51-b6229ac3d1a0', $$twee mogelijke uitkomsten van de onderhandelingen$$,
   $$economie-vwo-2021-ii-afvalwater-een-schone-zaak-context4.png$$,
   $$Er zijn twee mogelijke uitkomsten bij de onderhandelingen tussen ZW en de G4:
− De G4 investeert in een eigen gezamenlijke zuiveringsinstallatie.
− De G4 accepteert een korting op de heffing. Bij beide uitkomsten kunnen de overige bedrijven in de gemeente een sterkere (financiële) prikkel hebben gekregen om illegaal afvalwater te lozen.$$, 'inline'),
  ('de22df0f-3ea6-4d7a-9ed5-b3bf143e58a7', '21cfe451-ed82-410d-be51-b6229ac3d1a0', $$gegevensoverzicht casus ZW: vervuilingseenheid en formule heffingsbedrag$$,
   $$economie-vwo-2021-ii-afvalwater-een-schone-zaak-context5.png$$,
   $$Gegevensoverzicht casus ZW
Vervuilingseenheid (VE): een gemiddelde dat aangeeft hoe vervuild een liter afvalwater is
formule berekening totaal heffingsbedrag: aantal liters afvalwater x vervuilingseenheid x 70 euro$$, 'inline'),
  ('fba0d249-27f4-4fb8-9def-e14c727e861e', '21cfe451-ed82-410d-be51-b6229ac3d1a0', $$tabel 1: klasse-indeling naar vervuilingseenheid$$,
   $$economie-vwo-2021-ii-afvalwater-een-schone-zaak-context6.png$$,
   $$Tabel 1 klasse-indeling naar vervuilingseenheid
klasse | vervuilingseenheid | klasse | vervuilingseenheid
0 | 0 | 8 | 0,023
1 | 0,001 | 9 | 0,036
2 | 0,0016 | 10 | 0,056
3 | 0,0025 | 11 | 0,088
4 | 0,0039 | 12 | 0,14
5 | 0,006 | 13 | 0,21
6 | 0,0094 | 14 | 0,33
7 | 0,015 | 15 | 0,5$$, 'inline'),
  ('54be06e1-452f-4550-a0e2-22401795b506', '21cfe451-ed82-410d-be51-b6229ac3d1a0', $$tabel 2: bedrijfsgegevens afvalwater van de G4$$,
   $$economie-vwo-2021-ii-afvalwater-een-schone-zaak-context7.png$$,
   $$Tabel 2 bedrijfsgegevens afvalwater van de G4
bedrijf | klasse | Aantal liters afvalwater per jaar
A | 8 | 60.000
B | 7 | 80.000
C | 11 | 50.000
D | 10 | 40.000$$, 'inline'),
  ('41ea7468-81fa-4b1d-a127-2d165e485e58', '21cfe451-ed82-410d-be51-b6229ac3d1a0', $$tabel 3: verwachte kostenfunctie gezamenlijke zuiveringsinstallatie, met toelichting$$,
   $$economie-vwo-2021-ii-afvalwater-een-schone-zaak-context8.png$$,
   $$Tabel 3 verwachte kostenfunctie gezamenlijke zuiveringsinstallatie van de vier grote bedrijven samen
TK = 25VEtot + 300.000 | TK = totale kosten in euro’s
| VEtot = totaalaantal te verwerken vervuilingseenheden per jaar
Toelichting: Alleen de G4 maken gebruik van deze capaciteit tot waterzuivering. Het gezuiverde afvalwater wordt ingedeeld in klasse 0 als de bedrijven zelf hun afvalwater zuiveren en lozen. De totale kosten worden gedekt door de vier bedrijven naar rato van hoeveelheid afvalwater dat wordt aangeleverd.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('3af997b2-2610-4c70-a6d1-3a970bfe0752', 'c4c8c0bc-4d6a-4f87-b5a6-e462af353c93', 1,
