   $$economie-vwo-2021-ii-een-gewenste-prijsstijging-van-friet-vraag2.png$$, $$3p 2 Toon dit aan door middel van een berekening van de prijselasticiteit van de vraag naar friet van Willem’s cafetaria.$$, array['31ec084f-5193-400f-8a54-391b320faa25', 'cb3421dc-7723-488a-a211-eeae46d3b6a4']::uuid[]),
