   $$economie-vwo-2021-ii-verzekeren-op-maat-vraag6.png$$, $$1p 6 Zijn de potentiële verzekerden volgens de aannames risico-zoekend, risiconeutraal of risico-avers? Licht je antwoord toe.$$, array['15621321-010b-4394-9d2e-3eac7349bf31', 'd3382f77-85e7-4b03-b489-40d87dfc3549', '1e882cd6-0068-44fe-b572-0ae230c33607', '62591610-2e4c-40e8-9fc7-a85ddde22e75', '2d290da8-8ded-4832-83ff-d2be577e48cb']::uuid[]),
