   $$economie-vwo-2021-ii-verzekeren-op-maat-vraag9.png$$, $$2p 9 Leg de stelling van de onderzoeker uit.$$, array['2e842241-1362-4d09-b352-68bfcce4b6f6']::uuid[]),
