   '[{"domain": "Ruilen over de tijd", "subdomain": "Intertemporele ruil"}, {"domain": "Goede tijden, slechte tijden", "subdomain": "Begrotingsbeleid"}]'::jsonb,
   '["overheidsgarantie", "staatsschuld", "uitgestelde belastingheffing", "wanbetalingsrisico", "kredietgarantie"]'::jsonb,
