   $$economie-vwo-2021-ii-groei-op-de-klippen-vraag12.png$$, $$2p 12 Verklaar de bewering van de analist dat de Turkse overheid op termijn de belastingen zal moeten verhogen.$$, array['23c55f76-d36f-42e9-b00d-948cc54d030f']::uuid[]),
